<template>
  <AppLayout>
    <section v-if="auth.isAdmin" class="workspace-admin" aria-labelledby="admin-title">
      <header class="workspace-admin__header">
        <div><p>{{ t('workspace.eyebrow') }}</p><h1 id="admin-title">{{ t('workspace.adminTitle') }}</h1><span>{{ t('workspace.adminDescription') }}</span></div>
        <button class="btn btn-secondary btn-sm" type="button" :disabled="searchLoading" @click="reloadAll">{{ t('common.refresh') }}</button>
      </header>

      <form data-testid="admin-search-form" class="admin-filter glass-panel" @submit.prevent="submitSearch">
        <div class="admin-filter__primary">
          <label for="admin-name_prefix">{{ t('workspace.filters.name') }}<input id="admin-name_prefix" v-model="filters.name_prefix" name="name_prefix" /></label>
          <label for="admin-slug_prefix">{{ t('workspace.filters.slug') }}<input id="admin-slug_prefix" v-model="filters.slug_prefix" name="slug_prefix" /></label>
          <label for="admin-status">{{ t('common.status') }}<select id="admin-status" v-model="filters.status" name="status"><option value="">{{ t('workspace.filters.any') }}</option><option value="active">{{ t('workspace.statusLabels.active') }}</option><option value="suspended">{{ t('workspace.statusLabels.suspended') }}</option><option value="archived">{{ t('workspace.statusLabels.archived') }}</option><option value="pending_deletion">{{ t('workspace.statusLabels.pending_deletion') }}</option><option value="purging">{{ t('workspace.statusLabels.purging') }}</option><option value="deleted">{{ t('workspace.statusLabels.deleted') }}</option></select></label>
          <label for="admin-sort">{{ t('workspace.filters.sort') }}<select id="admin-sort" v-model="filters.sort" name="sort"><option value="id">ID</option><option value="name">{{ t('common.name') }}</option><option value="slug">{{ t('workspace.slug') }}</option><option value="created_at">{{ t('workspace.filters.created') }}</option><option value="updated_at">{{ t('workspace.filters.updated') }}</option></select></label>
          <label for="admin-direction">{{ t('workspace.filters.direction') }}<select id="admin-direction" v-model="filters.direction" name="direction"><option value="desc">{{ t('workspace.filters.newest') }}</option><option value="asc">{{ t('workspace.filters.oldest') }}</option></select></label>
