            <label for="admin-owner_user_id">{{ t('workspace.filters.ownerId') }}<input id="admin-owner_user_id" v-model="filterInput.owner_user_id" name="owner_user_id" type="number" min="1" step="1" /></label>
            <label for="admin-billing_owner_user_id">{{ t('workspace.filters.billingOwnerId') }}<input id="admin-billing_owner_user_id" v-model="filterInput.billing_owner_user_id" name="billing_owner_user_id" type="number" min="1" step="1" /></label>
            <label for="admin-type">{{ t('workspace.filters.type') }}<select id="admin-type" v-model="filters.type" name="type"><option value="">{{ t('workspace.filters.anyType') }}</option><option value="personal">{{ t('workspace.statusLabels.personal') }}</option><option value="organization">{{ t('workspace.statusLabels.organization') }}</option></select></label>
            <label for="admin-created_from">{{ t('workspace.filters.createdFromLocal') }}<input id="admin-created_from" v-model="filterInput.created_from" name="created_from" type="datetime-local" /></label>
            <label for="admin-created_to">{{ t('workspace.filters.createdToLocal') }}<input id="admin-created_to" v-model="filterInput.created_to" name="created_to" type="datetime-local" /></label>
            <label for="admin-updated_from">{{ t('workspace.filters.updatedFromLocal') }}<input id="admin-updated_from" v-model="filterInput.updated_from" name="updated_from" type="datetime-local" /></label>
            <label for="admin-updated_to">{{ t('workspace.filters.updatedToLocal') }}<input id="admin-updated_to" v-model="filterInput.updated_to" name="updated_to" type="datetime-local" /></label>
          </div>
        </details>
        <button class="btn btn-primary btn-sm" type="submit">{{ t('common.search') }}</button>
      </form>

      <div class="admin-overview-grid">
        <article class="admin-panel">
          <header><h2>{{ t('workspace.overview') }}</h2><span class="status-badge" :data-state="overview?.state || 'unknown'">{{ labelState(overview?.state) }}</span></header>
