          <template v-else-if="overview">
            <dl><div v-for="(count, key) in overview.counts" :key="key"><dt>{{ labelKey(String(key)) }}</dt><dd>{{ countLabel(count) }}</dd></div><div><dt>{{ t('workspace.workerExceptions') }}</dt><dd>{{ countLabel(overview.worker_exceptions) }}</dd></div><div><dt>{{ t('workspace.unknownWorkerLiveness') }}</dt><dd>{{ countLabel(overview.unknown_worker_liveness) }}</dd></div></dl>
            <div v-if="overview.issues.length" class="evidence-list"><strong>{{ t('workspace.diagnosticIssues') }}</strong><span v-for="issue in overview.issues" :key="`${issue.code}:${issue.scope}`">{{ issue.code }}: {{ issue.reason }}</span></div>
          </template>
          <p v-else class="workspace-state">{{ t('common.loading') }}</p>
        </article>
        <article class="admin-panel">
          <header><h2>{{ t('workspace.operations') }}</h2><span class="status-badge" :data-state="jobs?.state || 'unknown'">{{ labelState(jobs?.state) }}</span></header>
          <p v-if="jobsError" class="inline-error" role="alert">{{ t('workspace.adminUnavailable') }}</p>
