            <template v-if="jobs.export_rotation">
              <span>{{ t('workspace.rotationState') }}: {{ labelState(jobs.export_rotation.state) }}</span>
              <span>{{ t('workspace.rotationCertification') }}: {{ jobs.export_rotation.rotation_certified ? t('common.yes') : t('workspace.rotationNotCertified') }}</span>
              <span>{{ t('workspace.rotationFormat') }}: {{ jobs.export_rotation.format }} · {{ t('workspace.singleKeyNoId') }}: {{ boolLabel(jobs.export_rotation.single_key_no_id) }}</span>
              <span>{{ t('workspace.instanceCapabilities') }}: {{ t('workspace.keyAvailable') }} {{ boolLabel(jobs.export_rotation.capabilities.key_available) }} · {{ t('workspace.exportEnabled') }} {{ boolLabel(jobs.export_rotation.capabilities.export_enabled) }} · {{ t('workspace.purgeEnabled') }} {{ boolLabel(jobs.export_rotation.capabilities.purge_enabled) }}</span>
              <span>{{ t('workspace.rotationScope') }}: {{ labelState(jobs.export_rotation.capabilities.scope) }}</span>
              <span>{{ t('workspace.rotationCoverage') }}: {{ labelState(jobs.export_rotation.coverage) }}</span>
              <div class="evidence-list"><strong>{{ t('workspace.rotationInventory') }}</strong><span v-for="(count, key) in jobs.export_rotation.counts" :key="key">{{ labelKey(String(key)) }}: {{ countLabel(count) }}</span></div>
              <div v-if="jobs.export_rotation.prerequisites.length" class="evidence-list"><strong>{{ t('workspace.rotationPrerequisites') }}</strong><span v-for="item in jobs.export_rotation.prerequisites" :key="item">{{ item }}</span></div>
              <div v-if="jobs.export_rotation.issues.length" class="evidence-list"><strong>{{ t('workspace.diagnosticIssues') }}</strong><span v-for="issue in jobs.export_rotation.issues" :key="`${issue.code}:${issue.scope}`">{{ issue.code }}: {{ issue.reason }}</span></div>
            </template>
            <div v-if="jobs.webhook_failure_trend.length" class="evidence-list"><strong>{{ t('workspace.failureTrend') }}</strong><span v-for="bucket in jobs.webhook_failure_trend" :key="bucket.hour">{{ formatDate(bucket.hour) }}: {{ countLabel(bucket.count) }}</span></div>
            <div v-if="jobs.issues.length" class="evidence-list"><strong>{{ t('workspace.diagnosticIssues') }}</strong><span v-for="issue in jobs.issues" :key="`${issue.code}:${issue.scope}`">{{ issue.code }}: {{ issue.reason }}</span></div>
            <div class="worker-summary-table"><div v-for="worker in jobs.workers" :key="worker.worker" class="worker-summary-row"><strong>{{ worker.worker }}</strong><span>{{ labelState(worker.state) }}</span><span>{{ t('workspace.liveness') }}: {{ labelState(worker.liveness) }}</span><span>{{ t('workspace.dueLag') }}: {{ secondsLabel(worker.due_lag_seconds) }}</span></div></div>
          </div>
          <p v-else class="workspace-state">{{ t('common.loading') }}</p>
        </article>
      </div>

      <div v-if="searchError" class="workspace-state" role="alert">{{ t('workspace.adminUnavailable') }}</div>
      <div v-else-if="searchLoading" class="workspace-state" role="status">{{ t('common.loading') }}</div>
      <div v-else class="workspace-table-wrap">
        <table class="workspace-table"><thead><tr><th>{{ t('common.name') }}</th><th>{{ t('workspace.slug') }}</th><th>{{ t('common.status') }}</th><th>{{ t('workspace.filters.updated') }}</th><th>{{ t('common.actions') }}</th></tr></thead>
          <tbody><tr v-for="item in page.items" :key="item.id"><td><strong>{{ item.name }}</strong><small>#{{ item.id }}</small></td><td><code>{{ item.slug }}</code></td><td><span class="status-badge" :data-state="item.status">{{ labelState(item.status) }}</span></td><td>{{ formatDate(item.updated_at) }}</td><td><button :data-testid="`inspect-${item.id}`" class="btn btn-secondary btn-sm" type="button" @click="inspect(item.id)">{{ t('workspace.inspect') }}</button></td></tr></tbody>
        </table>
