      <section v-if="selectedId && detail?.workspace?.id === selectedId" data-testid="workspace-detail" class="admin-detail">
        <header><div><p>{{ t('workspace.selectedWorkspace') }}</p><h2>{{ detail.workspace?.name || t('workspace.unknownWorkspace') }}</h2><span>{{ t('workspace.observedAt') }}: {{ formatDate(detail.observed_at) }}</span></div><button data-testid="detail-refresh" class="btn btn-ghost btn-sm" type="button" @click="inspect(selectedId)">{{ t('common.refresh') }}</button></header>
        <div v-if="detailError" class="inline-error" role="alert">{{ msg('workspace.lastObserved', 'Last observed evidence; actions are disabled.') }}</div>
        <div class="detail-grid">
          <article><h3>{{ t('workspace.security') }}</h3><dl><div><dt>{{ t('workspace.owner') }}</dt><dd>{{ boolLabel(detail.owner_valid) }}</dd></div><div><dt>{{ t('workspace.adminBillingOwner') }}</dt><dd>{{ boolLabel(detail.billing_owner_valid) }}</dd></div><div><dt>{{ t('workspace.requireSso') }}</dt><dd>{{ boolLabel(detail.security_policy?.require_sso) }}</dd></div><div><dt>{{ t('workspace.requireMfa') }}</dt><dd>{{ boolLabel(detail.security_policy?.require_mfa) }}</dd></div><div><dt>{{ t('workspace.sessionMaxAge') }}</dt><dd>{{ secondsLabel(detail.security_policy?.session_max_age_seconds) }}</dd></div><div><dt>{{ t('workspace.invitationPolicy') }}</dt><dd>{{ labelState(detail.security_policy?.invitation_policy) }}</dd></div><div><dt>{{ t('workspace.externalMembers') }}</dt><dd>{{ boolLabel(detail.security_policy?.allow_external_members) }}</dd></div><div><dt>{{ t('workspace.workspaceJit') }}</dt><dd>{{ boolLabel(detail.security_policy?.workspace_jit_enabled) }}</dd></div><div><dt>{{ t('workspace.approvedIdpMode') }}</dt><dd>{{ labelState(detail.security_policy?.approved_identity_provider_mode) }}</dd></div></dl></article>
          <article><h3>{{ t('workspace.counts') }}</h3><dl><div v-for="(count, key) in detail.counts" :key="key"><dt>{{ labelKey(String(key)) }}</dt><dd>{{ countLabel(count) }}</dd></div></dl></article>
          <article><h3>{{ t('workspace.identity') }}</h3><template v-if="detail.identity"><section v-for="(identitySection, sectionKey) in detail.identity" :key="sectionKey" class="evidence-list"><strong>{{ labelKey(String(sectionKey)) }}: {{ labelState(identitySection.state) }}</strong><span>{{ t('workspace.coverage') }}: {{ labelState(identitySection.coverage) }} · {{ t('workspace.freshness') }}: {{ labelState(identitySection.freshness) }}</span><span v-for="connection in identitySection.items" :key="connection.id">{{ connection.type }} / {{ connection.status }}: {{ labelState(connection.state) }} · {{ connection.last_error_code || connection.last_validation_code || t('workspace.unknownEvidence') }}</span><span v-for="issue in identitySection.issues" :key="`${issue.code}:${issue.scope}`">{{ issue.code }}: {{ issue.reason }}</span></section></template><p v-else>{{ t('workspace.unknownEvidence') }}</p></article>
          <article><h3>{{ t('workspace.retention') }}</h3><dl><div v-for="row in detail.retention" :key="row.category"><dt>{{ labelKey(row.category) }}</dt><dd>{{ row.effective_days }}d / {{ row.minimum_days }}d · {{ row.protected ? t('common.yes') : t('common.no') }}</dd></div></dl><p v-if="!detail.retention.length">{{ t('common.noData') }}</p></article>
          <article><h3>{{ t('workspace.purge') }}: {{ labelState(detail.purge?.state) }}</h3><div class="evidence-list"><span v-for="blocker in detail.purge?.blockers || []" :key="blocker.code">{{ blocker.code }}: {{ blocker.reason }} · {{ blocker.count ? countLabel(blocker.count) : t('workspace.unknownEvidence') }}</span><span v-for="issue in detail.purge?.issues || []" :key="`${issue.code}:${issue.scope}`">{{ issue.code }}: {{ issue.reason }}</span></div></article>
          <article><h3>{{ t('workspace.recentAudit') }}</h3><div class="evidence-list"><span v-for="entry in detail.recent_audit" :key="entry.id">{{ entry.action }} · {{ entry.target_type }} #{{ entry.target_id ?? t('workspace.unknownEvidence') }} · {{ formatDate(entry.created_at) }}</span><span v-if="!detail.recent_audit.length">{{ t('common.noData') }}</span></div></article>
          <article v-if="detail.issues.length"><h3>{{ t('workspace.diagnosticIssues') }}</h3><div class="evidence-list"><span v-for="issue in detail.issues" :key="`${issue.code}:${issue.scope}`">{{ issue.code }}: {{ issue.reason }} · {{ issue.recommended_action }} · {{ issue.runbook }}</span></div></article>
        </div>
        <div class="detail-actions"><button v-if="detail.allowed_operations.includes('suspend')" data-testid="operation-suspend" class="btn btn-danger btn-sm" type="button" :disabled="staleDetail || operationPending" @click="openOperation('suspend')">{{ t('workspace.suspendWorkspace') }}</button><button v-if="detail.allowed_operations.includes('resume')" data-testid="operation-resume" class="btn btn-primary btn-sm" type="button" :disabled="staleDetail || operationPending" @click="openOperation('resume')">{{ t('workspace.activateWorkspace') }}</button><span v-if="staleDetail" class="stale-note">{{ t('workspace.actionsDisabledStale') }}</span></div>

        <div class="worker-table-wrap"><h3>{{ t('workspace.workerEvidence') }}</h3><table class="worker-table">
          <thead><tr><th>{{ t('workspace.worker') }}</th><th>{{ t('common.status') }}</th><th>{{ t('workspace.liveness') }}</th><th>{{ t('workspace.source') }}</th><th>{{ t('workspace.coverage') }}</th><th>{{ t('workspace.dueLag') }}</th><th>{{ t('workspace.oldestPending') }}</th><th>{{ t('workspace.pendingAlertAge') }}</th><th>{{ t('workspace.lastSuccessfulJob') }}</th><th>{{ t('workspace.lastSuccessfulScan') }}</th><th>{{ t('workspace.lastFailedAt') }}</th><th>{{ t('workspace.lastFailure') }}</th><th>{{ t('workspace.jobEvidence') }}</th></tr></thead>
          <tbody><tr v-for="worker in detail.jobs?.workers || []" :key="worker.worker">
            <td>{{ worker.worker }}</td><td>{{ labelState(worker.state) }}</td><td>{{ labelState(worker.liveness) }}</td><td>{{ worker.source }}</td><td>{{ labelState(worker.coverage) }} · {{ labelState(worker.freshness) }}</td>
            <td>{{ secondsLabel(worker.due_lag_seconds) }}<small v-if="worker.stored_scan_lag_seconds !== undefined">{{ t('workspace.storedScanLag') }}: {{ secondsLabel(worker.stored_scan_lag_seconds) }}</small></td>
            <td>{{ formatTimeEvidence(worker.oldest_pending) }}</td><td>{{ formatTimeEvidence(worker.pending_alert_age) }}</td>
            <td>{{ formatDate(worker.last_successful_job_at) }}</td><td>{{ formatDate(worker.last_successful_scan_at) }}</td><td>{{ formatDate(worker.last_failed_at) }}<small>{{ formatTimeEvidence(worker.latest_failure_time) }}</small></td>
            <td><span>{{ evidenceLabel(worker.last_failure) }}</span><small>{{ formatDate(worker.last_failure.source_time) }} · {{ labelState(worker.last_failure.source) }} · {{ labelState(worker.last_failure.coverage) }} · {{ labelState(worker.last_failure.freshness) }}</small></td>
            <td><div class="job-evidence">
              <span v-for="(count, key) in worker.counts" :key="key">{{ labelKey(String(key)) }}: {{ countLabel(count) }}</span><span v-if="worker.jobs_capped">{{ t('workspace.cappedEvidence') }}</span>
              <template v-for="job in worker.jobs" :key="job.id"><article class="job-evidence__item"><strong>{{ labelState(job.state) }} · {{ job.failure_code || t('workspace.unknownEvidence') }}</strong><span>{{ t('workspace.sourceTime') }}: {{ formatDate(job.source_time) }} · {{ t('workspace.observedAt') }}: {{ formatDate(job.observed_at) }}</span><span v-for="blocker in job.blockers || []" :key="blocker.code">{{ blocker.code }}: {{ blocker.reason }} · {{ formatDate(blocker.source_time) }} · {{ blocker.runbook }}</span><button v-if="job.retry_eligibility === 'eligible_requires_guarded_action'" type="button" class="btn btn-ghost btn-sm" :data-testid="`retry-${job.delivery_id}`" :disabled="staleDetail || operationPending" @click="openOperation('retry_webhook', job)">{{ t('workspace.retryWebhook') }}</button><span v-else-if="job.retry_eligibility" class="stale-note">{{ t('workspace.retryEligibility') }}: {{ labelState(job.retry_eligibility) }}</span></article></template>
              <div v-for="issue in worker.issues" :key="`${issue.code}:${issue.scope}`" class="job-evidence__item"><strong>{{ issue.code }}</strong><span>{{ issue.reason }} · {{ issue.recommended_action }}</span><span>{{ issue.runbook }} · {{ formatDate(issue.observed_at) }}</span></div><span>{{ t('workspace.runbook') }}: {{ worker.runbook }}</span>
            </div></td>
          </tr></tbody>
        </table></div>
      </section>
      <div v-if="operationOpen" data-testid="admin-operation-dialog" class="modal-overlay" role="dialog" aria-modal="true" aria-labelledby="operation-title" @keydown="trapFocus" @click.self="closeOperation"><div ref="dialogRef" class="modal-content"><h2 id="operation-title">{{ operationAction === 'retry_webhook' ? t('workspace.retryWebhookTitle') : operationAction === 'suspend' ? t('workspace.suspendWorkspace') : t('workspace.activateWorkspace') }}</h2><p>{{ t('workspace.confirmTarget', { name: detail?.workspace?.name || '' }) }}</p><p v-if="retryTarget" class="evidence-note">{{ t('workspace.retryEvidence', { attempts: retryTarget.attempts }) }}</p><form data-testid="admin-confirm-form" @submit.prevent="confirmOperation"><label>{{ t('workspace.reason') }}<textarea name="operation-reason" v-model="operationReason" maxlength="500" required /></label><label>{{ t('workspace.confirmation') }}<input name="operation-confirmation" v-model="operationConfirmation" required /></label><div class="dialog-actions"><button class="btn btn-ghost" type="button" @click="closeOperation">{{ t('common.cancel') }}</button><button class="btn btn-primary" type="submit" :disabled="operationPending || !operationReason.trim() || !operationConfirmation.trim()">{{ operationPending ? t('common.loading') : t('common.confirm') }}</button></div><p v-if="operationError" class="inline-error" role="alert">{{ t(operationError) }}</p></form></div></div>
      <TotpStepUpDialog :controller="stepUp" :on-verify="verifyStepUp" safe-errors />
    </section>
  </AppLayout>
</template>

<script setup lang="ts">
import { nextTick, onBeforeUnmount, onMounted, reactive, ref, watch } from 'vue'
import { useI18n } from 'vue-i18n'
import AppLayout from '@/components/layout/AppLayout.vue'
import { workspaceAPI, type Workspace } from '@/api/workspace'
import { enterpriseAdminAPI, type AdminAction, type AdminCount, type AdminDiagnosticsOverview, type AdminJobSummary, type AdminJobsDiagnostics, type AdminOperationInput, type AdminTimeEvidence, type AdminWorkspaceDiagnostics } from '@/api/enterpriseAdmin'
import { useAppStore } from '@/stores/app'; import { useAuthStore } from '@/stores/auth'; import { browserSessionIdentity } from '@/utils/workspaceSecurity'; import { totpAPI } from '@/api/totp'
import TotpStepUpDialog from '@/components/auth/TotpStepUpDialog.vue'; import { useStepUp, isStepUpCancelled } from '@/composables/useStepUp'
const { t } = useI18n(); const app = useAppStore(); const auth = useAuthStore()
const stepUp = useStepUp(); let operationTrigger: HTMLElement | null = null; let operationProofToken = ''
const page = reactive({ items: [] as Workspace[], total: 0, pages: 1, page: 1, total_capped: false, observed_at: '' })
const filters = reactive({ workspace_id: undefined as number | undefined, owner_user_id: undefined as number | undefined, billing_owner_user_id: undefined as number | undefined, name_prefix: '', slug_prefix: '', status: '', type: '', created_from: '', created_to: '', updated_from: '', updated_to: '', sort: 'id' as 'id' | 'name' | 'slug' | 'created_at' | 'updated_at', direction: 'desc' as 'asc' | 'desc', page: 1, page_size: 20 })
const filterInput = reactive({ workspace_id: '', owner_user_id: '', billing_owner_user_id: '', created_from: '', created_to: '', updated_from: '', updated_to: '' })
const overview = ref<AdminDiagnosticsOverview | null>(null); const jobs = ref<AdminJobsDiagnostics | null>(null); const selectedId = ref<number | null>(null); const detail = ref<AdminWorkspaceDiagnostics | null>(null)
const searchLoading = ref(false); const searchError = ref(false); const overviewError = ref(false); const jobsError = ref(false); const detailError = ref(false); const staleDetail = ref(false); const operationOpen = ref(false); const operationPending = ref(false); const operationAction = ref<AdminAction>('suspend'); const operationReason = ref(''); const operationConfirmation = ref(''); const operationError = ref(''); const retryTarget = ref<{ webhookId: number; deliveryId: number; attempts: number; lastAttemptAt?: string | null } | null>(null); const dialogRef = ref<HTMLElement | null>(null); let alive = true; let searchGeneration = 0; let overviewGeneration = 0; let detailGeneration = 0; let authSnapshot = browserSessionIdentity(); let searchController: AbortController | null = null; let overviewController: AbortController | null = null; let jobsController: AbortController | null = null; let detailController: AbortController | null = null; let operationController: AbortController | null = null
const msg = (key: string, fallback: string, values?: Record<string, unknown>) => { const value = t(key, values || {}); return value === key || value.startsWith(`${key}.`) ? fallback.replace('{count}', String(values?.count ?? '')) : value }
const countLabel = (count?: AdminCount | null) => !count || !count.available ? msg('workspace.unknownEvidence', 'Unknown') : count.capped ? msg('workspace.countLowerBound', 'At least {count}', { count: count.value ?? 0 }) : String(count.value ?? 0)
const labelState = (state?: string | null) => state ? t(`workspace.states.${state}`, state) : msg('workspace.unknownEvidence', 'Unknown')
const labelKey = (key: string) => t(`workspace.countLabels.${key}`, key)
const boolLabel = (value: boolean | null | undefined) => value === null || value === undefined ? msg('workspace.unknownEvidence', 'Unknown') : value ? t('common.yes') : t('common.no')
const formatDate = (value?: string | null) => value ? new Date(value).toLocaleString() : msg('workspace.unknownEvidence', 'Unknown')
const secondsLabel = (value?: number | null) => value === null || value === undefined ? msg('workspace.unknownEvidence', 'Unknown') : `${value} ${t('workspace.seconds')}`
const formatTimeEvidence = (value?: AdminTimeEvidence | null) => !value?.available ? msg('workspace.unknownEvidence', 'Unknown') : `${secondsLabel(value.age_seconds)} · ${formatDate(value.value)} · ${labelState(value.source)} · ${labelState(value.coverage)} · ${labelState(value.freshness)}`
const evidenceLabel = (value: { value?: string | null; code?: string | null; available?: boolean } | null | undefined) => value?.available ? value.value || value.code || msg('workspace.unknownEvidence', 'Unknown') : msg('workspace.unknownEvidence', 'Unknown')
function cancelDiagnostics() { overviewGeneration++; overviewController?.abort(); jobsController?.abort(); overviewController = null; jobsController = null }
function cancelReads() { searchGeneration++; detailGeneration++; cancelDiagnostics(); searchController?.abort(); detailController?.abort(); operationController?.abort(); searchController = null; detailController = null; operationController = null }
function currentAuth() { return browserSessionIdentity() === authSnapshot && auth.isAdmin }
function localDateTimeToRFC3339(value: string) { if (!value) return ''; const date = new Date(value); return Number.isNaN(date.getTime()) ? '' : date.toISOString() }
function positiveFilter(value: string | number) { if (value === '' || value === null || value === undefined) return undefined; const parsed = Number(value); return Number.isSafeInteger(parsed) && parsed > 0 ? parsed : undefined }
async function loadOverviewAndJobs() { cancelDiagnostics(); const expected = ++overviewGeneration; const oc = new AbortController(); const jc = new AbortController(); overviewController = oc; jobsController = jc; overviewError.value = false; jobsError.value = false; enterpriseAdminAPI.overview(oc.signal).then(value => { if (alive && expected === overviewGeneration && currentAuth()) overview.value = value }).catch(error => { if (alive && expected === overviewGeneration && error?.code !== 'ERR_CANCELED') overviewError.value = true }); enterpriseAdminAPI.jobs(jc.signal).then(value => { if (alive && expected === overviewGeneration && currentAuth()) jobs.value = value }).catch(error => { if (alive && expected === overviewGeneration && error?.code !== 'ERR_CANCELED') jobsError.value = true }) }
async function loadSearch() { searchController?.abort(); const controller = new AbortController(); searchController = controller; const expected = ++searchGeneration; searchLoading.value = true; searchError.value = false; try { const params = { workspace_id: filters.workspace_id, owner_user_id: filters.owner_user_id, billing_owner_user_id: filters.billing_owner_user_id, name_prefix: filters.name_prefix || undefined, slug_prefix: filters.slug_prefix || undefined, status: filters.status || undefined, type: filters.type || undefined, created_from: filters.created_from || undefined, created_to: filters.created_to || undefined, updated_from: filters.updated_from || undefined, updated_to: filters.updated_to || undefined, sort: filters.sort, direction: filters.direction, page: filters.page, page_size: filters.page_size }; const result = await workspaceAPI.adminList({ ...params, signal: controller.signal }); if (alive && expected === searchGeneration && currentAuth()) Object.assign(page, result) } catch (error) { if (alive && expected === searchGeneration && (error as { code?: string })?.code !== 'ERR_CANCELED') searchError.value = true } finally { if (alive && expected === searchGeneration) searchLoading.value = false } }
function submitSearch() { filters.workspace_id = positiveFilter(filterInput.workspace_id); filters.owner_user_id = positiveFilter(filterInput.owner_user_id); filters.billing_owner_user_id = positiveFilter(filterInput.billing_owner_user_id); filters.created_from = localDateTimeToRFC3339(filterInput.created_from); filters.created_to = localDateTimeToRFC3339(filterInput.created_to); filters.updated_from = localDateTimeToRFC3339(filterInput.updated_from); filters.updated_to = localDateTimeToRFC3339(filterInput.updated_to); filters.page = 1; void loadSearch() } function goPage(next: number) { filters.page = next; void loadSearch() } function reloadAll() { void loadSearch(); void loadOverviewAndJobs() }
async function inspect(id: number) { const previous = detail.value; const sameTarget = previous?.workspace?.id === id; selectedId.value = id; if (!sameTarget) detail.value = null; detailController?.abort(); const controller = new AbortController(); detailController = controller; const expected = ++detailGeneration; detailError.value = false; staleDetail.value = sameTarget; try { const result = await enterpriseAdminAPI.diagnostics(id, controller.signal); if (alive && expected === detailGeneration && selectedId.value === id && currentAuth()) { detail.value = result; staleDetail.value = false } } catch (error) { const code = (error as { code?: string })?.code; if (alive && expected === detailGeneration && selectedId.value === id && code !== 'ERR_CANCELED') { detailError.value = true; staleDetail.value = sameTarget } } }
function openOperation(action: AdminAction, job?: AdminJobSummary) { operationTrigger = document.activeElement as HTMLElement; operationAction.value = action; retryTarget.value = job?.webhook_id && job.delivery_id ? { webhookId: job.webhook_id, deliveryId: job.delivery_id, attempts: job.attempts ?? 0, lastAttemptAt: job.last_attempt_at } : null; operationReason.value = ''; operationConfirmation.value = action === 'retry_webhook' && job?.delivery_id ? `retry_webhook:${job.delivery_id}` : `${action}:${selectedId.value}`; operationError.value = ''; operationOpen.value = true; nextTick(() => dialogRef.value?.querySelector<HTMLElement>('textarea, input')?.focus()) } function closeOperation() { if (operationPending.value) return; operationOpen.value = false; operationController?.abort(); retryTarget.value = null; nextTick(() => operationTrigger?.focus()) } function trapFocus(event: KeyboardEvent) { if (event.key === 'Escape') return closeOperation(); if (event.key !== 'Tab' || !dialogRef.value) return; const focusable = [...dialogRef.value.querySelectorAll<HTMLElement>('button,input,textarea')].filter(el => !el.hasAttribute('disabled')); const first = focusable[0]; const last = focusable[focusable.length - 1]; if (event.shiftKey && document.activeElement === first) { event.preventDefault(); last?.focus() } else if (!event.shiftKey && document.activeElement === last) { event.preventDefault(); first?.focus() } }
async function verifyStepUp(code: string, signal: AbortSignal) { const upgraded = await totpAPI.upgradeSessionMFA(code, { signal, sessionProofAccessToken: operationProofToken }); auth.adoptStoredSessionTokens(upgraded); operationProofToken = upgraded.access_token }
async function confirmOperation() { if (operationPending.value || !detail.value || !selectedId.value || detail.value.workspace?.id !== selectedId.value || staleDetail.value || !currentAuth()) return; const target = detail.value.workspace; const retry = retryTarget.value; if (operationAction.value !== 'retry_webhook' && !target?.updated_at) { operationError.value = 'workspace.errors.conflict'; return } if (operationAction.value === 'retry_webhook' && (!retry || !retry.webhookId || !retry.deliveryId)) { operationError.value = 'workspace.errors.conflict'; return } const body: AdminOperationInput = { action: operationAction.value, reason: operationReason.value.trim(), confirmation: operationConfirmation.value.trim(), idempotency_key: crypto.randomUUID(), expected_updated_at: operationAction.value === 'retry_webhook' ? undefined : target?.updated_at, expected_attempts: operationAction.value === 'retry_webhook' ? retry?.attempts : undefined, expected_last_attempt_at: operationAction.value === 'retry_webhook' ? retry?.lastAttemptAt || '' : undefined }; const id = selectedId.value; operationPending.value = true; operationController = new AbortController(); const expectedSession = browserSessionIdentity(); operationProofToken = localStorage.getItem('auth_token') || ''; try { const request: () => Promise<unknown> = operationAction.value === 'retry_webhook' ? () => enterpriseAdminAPI.retryWebhook(id, retry!.webhookId, retry!.deliveryId, body, { signal: operationController!.signal, preserveAuthSessionOnFailure: true, sessionProofAccessToken: operationProofToken }) : () => workspaceAPI.adminSetStatus(id, body, { signal: operationController!.signal, preserveAuthSessionOnFailure: true, sessionProofAccessToken: operationProofToken }); await stepUp.run(request); if (!alive || expectedSession !== browserSessionIdentity() || !currentAuth()) return; operationOpen.value = false; retryTarget.value = null; staleDetail.value = true; detail.value = null; app.showSuccess(t('common.saved')); void inspect(id); void loadSearch(); void loadOverviewAndJobs() } catch (error) { if (isStepUpCancelled(error)) return; if (alive && expectedSession === browserSessionIdentity()) { operationError.value = 'workspace.errors.operation'; app.showError(t(operationError.value)) } } finally { if (alive) operationPending.value = false } }
function clearSensitiveState() { cancelReads(); Object.assign(page, { items: [], total: 0, pages: 1, page: 1, total_capped: false, observed_at: '' }); searchLoading.value = false; searchError.value = false; selectedId.value = null; detail.value = null; overview.value = null; jobs.value = null; operationOpen.value = false; staleDetail.value = false }
function clearIfSessionChanged() { const current = browserSessionIdentity(); if (current !== authSnapshot) { authSnapshot = current; clearSensitiveState() } }
