watch(() => auth.isAdmin, admin => { if (!admin) { authSnapshot = browserSessionIdentity(); clearSensitiveState() } }); watch(() => [auth.token, auth.user?.id], clearIfSessionChanged); onMounted(() => { authSnapshot = browserSessionIdentity(); window.addEventListener('storage', handleStorageChange); void loadSearch(); void loadOverviewAndJobs() }); onBeforeUnmount(() => { alive = false; window.removeEventListener('storage', handleStorageChange); cancelReads() })
</script>

